(1572, 1, '2024-05-24 17:25:25', '2024-05-24 17:25:25', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"66.66%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:66.66%\"><!-- wp:paragraph -->\n<p><a href=\"https://torrebalta810.org.pe/documentos/reglamento-interno/\">Reglamento Interno</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://torrebalta810.org.pe/porcentaje-de-participacion/\">Porcentaje de Participaci&oacute;n por Unidad Inmobiliaria</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://torrebalta810.org.pe/porcentaje-de-participacion/\">Normas B&aacute;sicas de Convivencia</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://torrebalta810.org.pe/documentos/solicitud-permiso-para-remodelacion/\">Solicitud Permiso para Remodelción</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://torrebalta810.org.pe/registro-de-inquilinos/\">Registro de Inquilinos</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://torrebalta810.org.pe/el-condominio/registro-de-propietarios/\">Registro de Propietarios</a> </p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.33%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vivid-red\"}}}},\"textColor\":\"vivid-red\",\"fontSize\":\"medium\"} -->\n<p class=\"has-vivid-red-color has-text-color has-link-color has-medium-font-size\"><strong>Numeros de Emergencia</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Serenazgo</strong> 01 350 9090</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Whatsapp</strong> 942 113 691</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Bomberos</strong> 116 </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Policia Nacional</strong> 105</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":107,\"width\":\"207px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><a href=\"https://www.miraflores.gob.pe/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://torrebalta810.org.pe/wp-content/uploads/2024/03/miraflores.jpg\" alt=\"\" class=\"wp-image-107\" style=\"width:207px;height:auto\" title=\"Municipalidad de Miraflores\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p id=\"aboutus\"></p>\n<!-- /wp:paragraph -->', 'Documentos', '', 'inherit', 'closed', 'closed', '', '1182-revision-v1', '', '', '2024-05-24 17:25:25', '2024-05-24 17:25:25', '', 1182, 'https://torrebalta810.org.pe/?p=1572', 0, 'revision', '', 0),
